package org.apache.commons.lang3.math;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_3_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        String numberStr = "1.12345678"; // 8 decimal places
        Number result = NumberUtils.createNumber(numberStr);

        // Before the fix, this would incorrectly be a Float, causing precision loss
        assertTrue("Expected a Double for 8 decimal places", result instanceof Double);
        assertEquals("Expected precise value", 1.12345678, result.doubleValue(), 0.0);
    }
}

